import re
from taf.ul.mobile.ui.android.adb_proxy.adb_proxy import AdbProxy
from taf.ul.mobile.ui.android.exceptions import ParcelDataNotParsed


class Android10AdbProxy(AdbProxy):

    _getActiveSubscriptionInfoForSimSlotIndex = 5
    _getDefaultDataSubId = 32
    _getSlotIndex = 27

    """
    using adb shell command to call Android services.
    get SIM card subscription info with under function list

    https://android.googlesource.com/platform/frameworks/base/+/refs/tags/
    android-10.0.0_r46/telephony/java/com/android/internal/telephony/ISub.aidl
    """

    def is_sim_card_active_for_slot_index(self, slot_index):
        command = "adb shell service call isub {} i32 {}".format(self._getActiveSubscriptionInfoForSimSlotIndex,
                                                                 slot_index)
        output = self._executor.execute(self._construct_command(command))
        return self._parse_parcel_data_for_getting_active_status(output)

    @staticmethod
    def _parse_parcel_data_for_getting_active_status(message):
        """
        under is output of adb command, the second hex value (00000001) from the bottom
        indicate the status of SIM card, 00000001 is active, 00000000 is inactive.
        xxxx>adb shell service call isub 5 i32 0
        Result: Parcel(
          0x00000000: 00000000 00000001 00000002 00000014 '................'
          0x00000010: 00390038 00300030 00300030 00390031 '8.9.0.0.0.0.1.9.'
          0x00000020: 00320031 00300030 00320030 00360030 '1.2.0.0.0.2.0.6.'
          ...
          0x000002c0: 00000000 00000003 00000005 00360032 '............2.6.'
          0x000002d0: 00300032 00000033 00000005 00360032 '2.0.3.......2.6.'
          0x000002e0: 00300032 00000033 00000005 00360032 '2.0.3.......2.6.'
          0x000002f0: 00300032 00000033 ffffffff 00000001 '2.0.3...........'
          0x00000300: ffffffff                            '....            '
        """
        hex_data_list = re.findall(r"([\da-f]{8})\s", message)
        if not hex_data_list:
            raise ParcelDataNotParsed(message)
        return hex_data_list[-2] == '00000001'

    def _get_default_data_sub_id(self):
        """
        Result: Parcel(00000000 00000002   '........')
        The last value 00000002 is default mobile data subscription id.
        """
        output = self._executor.execute(self._construct_command("adb shell service call isub {}".format(self._getDefaultDataSubId)))
        hex_data_list = re.findall(r"([\da-f]{8})\s", output)
        if len(hex_data_list) != 2:
            raise ParcelDataNotParsed(output)

        return int(hex_data_list[-1])

    def _get_slot_index_by_sub_id(self, sub_id):
        """
        Parcel(00000000 00000001   '........')
        The last value 00000001 is sim card slot index of specified subscription id.
        """
        output = self._executor.execute(self._construct_command("adb shell service call isub {} i32 {}".format(self._getSlotIndex, sub_id)))
        hex_data_list = re.findall(r"([\da-f]{8})\s", output)
        if len(hex_data_list) != 2:
            raise ParcelDataNotParsed(output)
        return int(hex_data_list[-1])
